:root {
  --bg: #1e1e2e;
  --surface: #2a2a3c;
  --primary: #7c6af7;
  --primary-light: #a89bff;
  --text: #e0e0f0;
  --matched: #3a3a5c;
  --card-back: #4a4a6a;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-container {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.game-header {
  text-align: center;
  margin-bottom: 20px;
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 12px;
  color: var(--primary-light);
}

.status-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

#move-counter {
  font-size: 1rem;
  font-weight: 600;
}

button {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  padding: 10px 20px;
  border: none;
  border-radius: 8px;
  background: var(--primary);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

button:hover {
  background: var(--primary-light);
}

button:focus-visible {
  outline: 3px solid var(--primary-light);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  justify-content: center;
  margin: 0 auto;
}

.card {
  aspect-ratio: 1;
  border-radius: 10px;
  cursor: pointer;
  background: var(--card-back);
  border: 2px solid transparent;
  transition: transform 0.2s, background 0.2s, border-color 0.2s;
  position: relative;
  overflow: hidden;
  font-size: 0;
}

.card::after {
  content: '?';
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.3);
  transition: opacity 0.2s;
}

.card.flipped::after,
.card.matched::after {
  opacity: 0;
}

.card.flipped,
.card.matched {
  border-color: var(--primary-light);
}

.card.matched {
  cursor: default;
  opacity: 0.85;
  border-color: var(--primary);
}

.card:hover:not(.flipped):not(.matched) {
  transform: scale(1.04);
  background: var(--primary);
}

.card:focus-visible {
  outline: 3px solid var(--primary-light);
  outline-offset: 2px;
}

.card:active:not(.flipped):not(.matched) {
  transform: scale(0.97);
}

.win-message {
  text-align: center;
  margin-top: 20px;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--primary-light);
}

@media (max-width: 420px) {
  .game-container {
    padding: 16px;
  }
  .game-board {
    gap: 6px;
  }
  h1 {
    font-size: 1.25rem;
  }
  button {
    padding: 8px 14px;
    font-size: 0.9rem;
  }
  .card::after {
    font-size: 1.2rem;
  }
}

const COLORS = [
  '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
  '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
];

const board = document.getElementById('game-board');
const moveCounter = document.getElementById('move-counter');
const winMessage = document.getElementById('win-message');
const newGameBtn = document.getElementById('new-game-btn');

let cards = [];
let flipped = [];
let matchedCount = 0;
let moves = 0;
let lockBoard = false;

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function createDeck() {
  const deck = [];
  COLORS.forEach((color, index) => {
    deck.push({ color, pairId: index });
    deck.push({ color, pairId: index });
  });
  return shuffle(deck);
}

function renderBoard() {
  board.innerHTML = '';
  cards = createDeck();
  cards.forEach((card, i) => {
    const el = document.createElement('button');
    el.type = 'button';
    el.className = 'card';
    el.setAttribute('aria-label', 'Hidden card');
    el.dataset.index = i;
    el.dataset.pairId = card.pairId;
    el.addEventListener('click', () => flipCard(el));
    board.appendChild(el);
  });
}

function flipCard(el) {
  if (lockBoard) return;
  if (el.classList.contains('flipped') || el.classList.contains('matched')) return;
  if (flipped.length === 2) return;

  el.classList.add('flipped');
  el.style.background = cards[el.dataset.index].color;
  el.setAttribute('aria-label', 'Card revealed');
  flipped.push(el);

  if (flipped.length === 2) {
    moves++;
    moveCounter.textContent = `Moves: ${moves}`;
    checkMatch();
  }
}

function checkMatch() {
  const [a, b] = flipped;
  if (a.dataset.pairId === b.dataset.pairId) {
    a.classList.add('matched');
    b.classList.add('matched');
    a.setAttribute('aria-label', 'Matched card');
    b.setAttribute('aria-label', 'Matched card');
    matchedCount++;
    flipped = [];
    if (matchedCount === COLORS.length) {
      winMessage.hidden = false;
      winMessage.textContent = `You win! 🎉 Completed in ${moves} moves.`;
    }
  } else {
    lockBoard = true;
    setTimeout(() => {
      a.classList.remove('flipped');
      b.classList.remove('flipped');
      a.style.background = '';
      b.style.background = '';
      a.setAttribute('aria-label', 'Hidden card');
      b.setAttribute('aria-label', 'Hidden card');
      flipped = [];
      lockBoard = false;
    }, 800);
  }
}

function newGame() {
  flipped = [];
  matchedCount = 0;
  moves = 0;
  lockBoard = false;
  moveCounter.textContent = 'Moves: 0';
  winMessage.hidden = true;
  winMessage.textContent = '';
  renderBoard();
}

newGameBtn.addEventListener('click', newGame);

newGame();
